# EMBEDDED VECTOR STORE DATA - 56 chunks
_EMBEDDED_VS_B64 = """"""

# DECODE AND LOAD DATA AT MODULE LEVEL (not in init)
print("Loading vector store data...", flush=True)
_VS_DATA = {}
try:
    _data_bytes = base64.b64decode(_EMBEDDED_VS_B64)
    _VS_DATA = json.loads(_data_bytes.decode('utf-8'))
    print(f"✓ Loaded {len(_VS_DATA.get('chunks', []))} chunks", flush=True)
except Exception as e:
    print(f"✗ Failed to load: {e}", flush=True)
    _VS_DATA = {'chunks': [], 'vocab': {}, 'idf': {}}

