API_KEY = os.getenv('API_KEY', 'your_api_key_here')

def validate_api_key():
    auth_header = request.headers.get('Authorization', '')
    if not auth_header.startswith('Bearer '):
        return False
    return auth_header[7:] == API_KEY

class VectorStore:
    def __init__(self):
        # Use pre-loaded global data
        self.chunks = _VS_DATA.get('chunks', [])
        self.vocab = {k: int(v) for k, v in _VS_DATA.get('vocab', {}).items()}
        self.idf = _VS_DATA.get('idf', {})
    
    def _tokenize(self, text):
        tokens = re.findall(r'\b\w+\b', text.lower())
        stop_words = {'the', 'a', 'an', 'and', 'or', 'but', 'in', 'on', 'at', 'to', 'for', 'of', 'with', 'by', 'from', 'is', 'are', 'was', 'were', 'be', 'been', 'it', 'this', 'that', 'these', 'those', 'i', 'you', 'he', 'she', 'we', 'they', 'what', 'which', 'who', 'when', 'where', 'why', 'how'}
        return [t for t in tokens if t not in stop_words and len(t) > 2]
    
    def _get_tfidf_vector(self, text):
        tokens = self._tokenize(text)
        vector = {}
        for token in tokens:
            if token in self.vocab:
                idx = self.vocab[token]
                idf = self.idf.get(token, 1.0)
                vector[idx] = vector.get(idx, 0) + idf
        return vector
    
    def _cosine_similarity(self, v1, v2):
        if not v1 or not v2:
            return 0.0
        dot = sum(v1.get(k, 0) * v2.get(k, 0) for k in set(v1.keys()) & set(v2.keys()))
        mag1 = math.sqrt(sum(v**2 for v in v1.values()))
        mag2 = math.sqrt(sum(v**2 for v in v2.values()))
        if mag1 == 0 or mag2 == 0:
            return 0.0
        return dot / (mag1 * mag2)
    
    def search(self, query, top_k=5):
        if not self.chunks:
            return []
        query_vec = self._get_tfidf_vector(query)
        scores = []
        for i, chunk in enumerate(self.chunks):
            chunk_vec = self._get_tfidf_vector(chunk.get('text', ''))
            sim = self._cosine_similarity(query_vec, chunk_vec)
            if sim > 0:
                scores.append((i, sim, chunk))
        scores.sort(key=lambda x: x[1], reverse=True)
        return [chunk for _, _, chunk in scores[:top_k]]
    
    def get_stats(self):
        unique_docs = set()
        by_type = defaultdict(int)
        for chunk in self.chunks:
            meta = chunk.get('metadata', {})
            file_path = meta.get('file_path')
            if file_path:
                unique_docs.add(file_path)
            doc_type = meta.get('doc_type', 'Unknown')
            by_type[doc_type] += 1
        return {
            'total_chunks': len(self.chunks),
            'unique_documents': len(unique_docs),
            'vocab_size': len(self.vocab),
            'chunks_by_type': dict(by_type)
        }

# Initialize
vector_store = VectorStore()

def generate_answer(question, search_results):
    if not search_results:
        return {
            'answer': 'I could not find relevant documents to answer your question. Please try another query.',
            'citations': [],
            'error': 'No matching documents found'
        }
    
    context = '\n\n'.join([r.get('text', '') for r in search_results[:5]])
    
    llm_provider = os.getenv('LLM_PROVIDER', 'deepseek')
    try:
        if llm_provider == 'deepseek':
            import urllib.request
            import json
            api_key = os.getenv('DEEPSEEK_API_KEY')
            if not api_key:
                return {'answer': 'LLM API key not configured', 'citations': [], 'error': 'Missing DEEPSEEK_API_KEY'}
            
            user_msg = f"Based on these documents:\n\n{context}\n\nAnswer this question: {question}"
            payload = {
                "model": "deepseek-chat",
                "messages": [
                    {"role": "system", "content": "You are a helpful assistant for document-based Q&A. Answer questions based on provided documents. Be concise and cite sources."},
                    {"role": "user", "content": user_msg}
                ],
                "temperature": 0.7,
                "max_tokens": 500
            }
            
            req = urllib.request.Request('https://api.deepseek.com/chat/completions',
                data=json.dumps(payload).encode('utf-8'),
                headers={'Content-Type': 'application/json', 'Authorization': f'Bearer {api_key}'},
                method='POST')
            
            with urllib.request.urlopen(req, timeout=30) as response:
                result = json.loads(response.read().decode('utf-8'))
                answer = result.get('choices', [{}])[0].get('message', {}).get('content', 'No response from LLM')
        else:
            answer = f"Based on the documents: {context[:300]}..."
    except Exception as e:
        answer = f"Error generating answer: {str(e)}"
    
    citations = []
    seen = set()
    for result in search_results:
        meta = result.get('metadata', {})
        file_path = meta.get('file_path')
        if file_path not in seen:
            citations.append(meta)
            seen.add(file_path)
    
    return {
        'answer': answer,
        'citations': citations,
        'error': None
    }

