@app.route('/', methods=['GET'])
@app.route('/index.html', methods=['GET'])
def serve_frontend():
    """Serve the frontend HTML"""
    return _FRONTEND_HTML, 200, {'Content-Type': 'text/html'}

@app.route('/health', methods=['GET'])
def health():
    stats = vector_store.get_stats()
    return jsonify({
        'status': 'ok',
        'message': 'Stonewater RAG API is running',
        'vector_store_chunks': stats['total_chunks']
    })

@app.route('/api/stats', methods=['GET'])
def stats():
    if not validate_api_key():
        return jsonify({'error': 'Unauthorized'}), 401
    store_stats = vector_store.get_stats()
    return jsonify({
        'status': 'success',
        'vector_store': store_stats,
        'documents': {'total': store_stats['unique_documents'], 'by_type': store_stats['chunks_by_type']}
    })

@app.route('/api/query', methods=['POST'])
def query():
    if not validate_api_key():
        return jsonify({'error': 'Unauthorized'}), 401
    data = request.get_json()
    question = data.get('question', '')
    if not question:
        return jsonify({'error': 'Question is required'}), 400
    try:
        search_results = vector_store.search(question, top_k=5)
        result = generate_answer(question, search_results)
        return jsonify({
            'status': 'success',
            'question': question,
            'answer': result['answer'],
            'citations': result['citations'],
            'error': result['error']
        })
    except Exception as e:
        return jsonify({'error': str(e), 'status': 'error'}), 500

@app.route('/api/documents', methods=['GET'])
def documents():
    if not validate_api_key():
        return jsonify({'error': 'Unauthorized'}), 401
    doc_list = []
    seen = set()
    for chunk in vector_store.chunks:
        meta = chunk.get('metadata', {})
        file_path = meta.get('file_path')
        if file_path and file_path not in seen:
            doc_list.append({
                'file_name': meta.get('file_name'),
                'doc_type': meta.get('doc_type'),
                'client_project': meta.get('client_project'),
                'file_path': meta.get('file_path')
            })
            seen.add(file_path)
    return jsonify({
        'status': 'success',
        'documents': doc_list,
        'count': len(doc_list)
    })

if __name__ == '__main__':
    port = int(os.getenv('FLASK_PORT', 5001))
    app.run(debug=True, port=port)
